-- =====================================================================================
--  COMPANY MANAGEMENT SYSTEM  -  MySQL 8.0 Database Script
--  Database : company_management_db
--  Company  : Orbitwave Technologies Pvt. Ltd. (fictional sample company)
--  Target   : MySQL 8.0.16+  (CHECK constraints are enforced from 8.0.16 onward)
--  Tool     : MySQL Workbench 8.x  /  mysql CLI  /  Python mysql-connector-python
--
--  The script is REPEATABLE: it drops and recreates the whole database every run.
--
--  SECTIONS
--    0.  Session setup
--    1.  Database creation
--    2.  Master tables        : departments, designations
--    3.  Core table           : employees  (+ circular FK departments.head -> employees)
--    4.  Role table           : managers
--    5.  Transaction tables   : attendance, leave_requests, payroll
--    6.  Project tables       : projects, employee_projects
--    7.  Review table         : performance_reviews
--    8.  Triggers
--    9.  Seed data            : departments -> designations -> employees -> department heads
--                               -> managers -> projects -> employee_projects -> leave_requests
--                               -> attendance -> payroll -> performance_reviews
--   10.  Views
--   11.  Stored procedures
--   12.  Data verification queries
--   13.  SQL practice examples (CREATE, INSERT, SELECT, WHERE, ORDER BY, GROUP BY, JOIN,
--        UPDATE, DELETE, subqueries, aggregates, transactions)
--   14.  Session restore
--
--  All monetary values are in Indian Rupees (INR). employees.salary is ANNUAL CTC.
-- =====================================================================================


-- =====================================================================================
-- SECTION 0 : SESSION SETUP
-- MySQL Workbench enables "Safe Updates" by default, which blocks UPDATE/DELETE
-- statements that are not filtered on a key column. We switch it off for this session
-- only and restore the original value in Section 14.
-- =====================================================================================
SET @OLD_SQL_SAFE_UPDATES = @@SQL_SAFE_UPDATES;
SET SQL_SAFE_UPDATES = 0;
SET NAMES utf8mb4;
SET time_zone = '+05:30';


-- =====================================================================================
-- SECTION 1 : DATABASE CREATION  (drop + recreate = repeatable script)
-- =====================================================================================
DROP DATABASE IF EXISTS company_management_db;

CREATE DATABASE company_management_db
    CHARACTER SET utf8mb4
    COLLATE utf8mb4_unicode_ci;

USE company_management_db;


-- =====================================================================================
-- SECTION 2 : MASTER TABLES
-- =====================================================================================

-- -------------------------------------------------------------------------------------
-- 2.1 departments
--     head_employee_id is linked to employees in Section 3 (circular reference),
--     because the employees table does not exist yet at this point.
-- -------------------------------------------------------------------------------------
CREATE TABLE departments (
    department_id      INT UNSIGNED      NOT NULL AUTO_INCREMENT,
    department_code    VARCHAR(10)       NOT NULL,
    department_name    VARCHAR(100)      NOT NULL,
    location           VARCHAR(60)       NOT NULL,
    annual_budget      DECIMAL(14,2)     NOT NULL DEFAULT 0.00,
    phone_extension    VARCHAR(6)            NULL,
    head_employee_id   INT UNSIGNED          NULL,
    is_active          BOOLEAN           NOT NULL DEFAULT TRUE,
    created_at         TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at         TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,

    CONSTRAINT pk_departments            PRIMARY KEY (department_id),
    CONSTRAINT uq_departments_code       UNIQUE (department_code),
    CONSTRAINT uq_departments_name       UNIQUE (department_name),
    CONSTRAINT chk_departments_budget    CHECK (annual_budget >= 0),
    CONSTRAINT chk_departments_code      CHECK (department_code = UPPER(department_code))
) ENGINE = InnoDB COMMENT = 'Company departments / business units';


-- -------------------------------------------------------------------------------------
-- 2.2 designations (job titles). Each designation belongs to one department and has
--     a salary band. The UNIQUE (designation_id, department_id) key lets employees use
--     a composite FK so an employee's designation always matches their department.
-- -------------------------------------------------------------------------------------
CREATE TABLE designations (
    designation_id     INT UNSIGNED      NOT NULL AUTO_INCREMENT,
    designation_title  VARCHAR(100)      NOT NULL,
    department_id      INT UNSIGNED      NOT NULL,
    job_level          TINYINT UNSIGNED  NOT NULL,
    min_salary         DECIMAL(12,2)     NOT NULL,
    max_salary         DECIMAL(12,2)     NOT NULL,
    is_managerial      BOOLEAN           NOT NULL DEFAULT FALSE,
    created_at         TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT pk_designations              PRIMARY KEY (designation_id),
    CONSTRAINT uq_designations_title        UNIQUE (designation_title),
    CONSTRAINT uq_designations_id_dept      UNIQUE (designation_id, department_id),
    CONSTRAINT fk_designations_department   FOREIGN KEY (department_id)
        REFERENCES departments (department_id),
    CONSTRAINT chk_designations_level       CHECK (job_level BETWEEN 1 AND 10),
    CONSTRAINT chk_designations_min_salary  CHECK (min_salary > 0),
    CONSTRAINT chk_designations_band        CHECK (max_salary >= min_salary)
) ENGINE = InnoDB COMMENT = 'Job titles with level and annual salary band (INR)';


-- =====================================================================================
-- SECTION 3 : CORE TABLE - employees
-- =====================================================================================
CREATE TABLE employees (
    employee_id         INT UNSIGNED      NOT NULL AUTO_INCREMENT,
    employee_code       VARCHAR(10)       NOT NULL,
    first_name          VARCHAR(50)       NOT NULL,
    last_name           VARCHAR(50)       NOT NULL,
    email               VARCHAR(120)      NOT NULL,
    phone               VARCHAR(15)       NOT NULL,
    date_of_birth       DATE              NOT NULL,
    gender              VARCHAR(10)       NOT NULL,
    department_id       INT UNSIGNED      NOT NULL,
    designation_id      INT UNSIGNED      NOT NULL,
    manager_id          INT UNSIGNED          NULL,
    salary              DECIMAL(12,2)     NOT NULL,
    joining_date        DATE              NOT NULL,
    exit_date           DATE                  NULL,
    address             VARCHAR(200)      NOT NULL,
    city                VARCHAR(60)       NOT NULL,
    state               VARCHAR(60)       NOT NULL,
    postal_code         CHAR(6)           NOT NULL,
    employment_type     VARCHAR(20)       NOT NULL DEFAULT 'Full-Time',
    employment_status   VARCHAR(20)       NOT NULL DEFAULT 'Active',
    performance_rating  DECIMAL(2,1)          NULL,
    created_at          TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,

    CONSTRAINT pk_employees                 PRIMARY KEY (employee_id),
    CONSTRAINT uq_employees_code            UNIQUE (employee_code),
    CONSTRAINT uq_employees_email           UNIQUE (email),
    CONSTRAINT uq_employees_phone           UNIQUE (phone),

    CONSTRAINT fk_employees_department      FOREIGN KEY (department_id)
        REFERENCES departments (department_id),
    CONSTRAINT fk_employees_designation     FOREIGN KEY (designation_id, department_id)
        REFERENCES designations (designation_id, department_id),
    CONSTRAINT fk_employees_manager         FOREIGN KEY (manager_id)
        REFERENCES employees (employee_id) ON DELETE SET NULL,

    CONSTRAINT chk_employees_code           CHECK (employee_code REGEXP '^EMP[0-9]{4}$'),
    CONSTRAINT chk_employees_email          CHECK (email LIKE '%_@_%._%'),
    CONSTRAINT chk_employees_phone          CHECK (phone REGEXP '^\\+91[6-9][0-9]{9}$'),
    CONSTRAINT chk_employees_gender         CHECK (gender IN ('Male', 'Female', 'Other')),
    CONSTRAINT chk_employees_salary         CHECK (salary > 0),
    CONSTRAINT chk_employees_min_age        CHECK (joining_date >= DATE_ADD(date_of_birth, INTERVAL 18 YEAR)),
    CONSTRAINT chk_employees_exit_date      CHECK (exit_date IS NULL OR exit_date >= joining_date),
    CONSTRAINT chk_employees_postal_code    CHECK (postal_code REGEXP '^[1-9][0-9]{5}$'),
    CONSTRAINT chk_employees_type           CHECK (employment_type IN ('Full-Time', 'Part-Time', 'Contract', 'Intern')),
    CONSTRAINT chk_employees_status         CHECK (employment_status IN
        ('Active', 'Probation', 'On Leave', 'Notice Period', 'Resigned', 'Terminated')),
    CONSTRAINT chk_employees_exit_status    CHECK (employment_status NOT IN ('Resigned', 'Terminated') OR exit_date IS NOT NULL),
    CONSTRAINT chk_employees_rating         CHECK (performance_rating IS NULL OR performance_rating BETWEEN 1.0 AND 5.0),

    INDEX idx_employees_name          (last_name, first_name),
    INDEX idx_employees_status        (employment_status),
    INDEX idx_employees_city          (city),
    INDEX idx_employees_joining_date  (joining_date),
    INDEX idx_employees_salary        (salary)
) ENGINE = InnoDB COMMENT = 'Employee master record';

-- Circular reference: department head is an employee. Added after employees exists.
ALTER TABLE departments
    ADD CONSTRAINT fk_departments_head FOREIGN KEY (head_employee_id)
        REFERENCES employees (employee_id) ON DELETE SET NULL;


-- =====================================================================================
-- SECTION 4 : ROLE TABLE - managers
--     Lists every employee who holds a people-manager role. employees.manager_id points
--     to employees.employee_id (self-reference); this table stores manager-specific
--     attributes such as level and appointment date.
-- =====================================================================================
CREATE TABLE managers (
    manager_id         INT UNSIGNED      NOT NULL AUTO_INCREMENT,
    employee_id        INT UNSIGNED      NOT NULL,
    department_id      INT UNSIGNED      NOT NULL,
    manager_level      VARCHAR(20)       NOT NULL,
    appointed_date     DATE              NOT NULL,
    is_active          BOOLEAN           NOT NULL DEFAULT TRUE,
    created_at         TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT pk_managers               PRIMARY KEY (manager_id),
    CONSTRAINT uq_managers_employee      UNIQUE (employee_id),
    CONSTRAINT fk_managers_employee      FOREIGN KEY (employee_id)
        REFERENCES employees (employee_id) ON DELETE CASCADE,
    CONSTRAINT fk_managers_department    FOREIGN KEY (department_id)
        REFERENCES departments (department_id),
    CONSTRAINT chk_managers_level        CHECK (manager_level IN
        ('Team Lead', 'Manager', 'Senior Manager', 'Director', 'Executive'))
) ENGINE = InnoDB COMMENT = 'Employees holding people-manager roles';


-- =====================================================================================
-- SECTION 5 : TRANSACTION TABLES
-- =====================================================================================

-- -------------------------------------------------------------------------------------
-- 5.1 attendance - one row per employee per working day
-- -------------------------------------------------------------------------------------
CREATE TABLE attendance (
    attendance_id      BIGINT UNSIGNED   NOT NULL AUTO_INCREMENT,
    employee_id        INT UNSIGNED      NOT NULL,
    attendance_date    DATE              NOT NULL,
    check_in           TIME                  NULL,
    check_out          TIME                  NULL,
    status             VARCHAR(20)       NOT NULL DEFAULT 'Present',
    work_hours         DECIMAL(4,2) GENERATED ALWAYS AS
                       (ROUND(TIME_TO_SEC(TIMEDIFF(check_out, check_in)) / 3600, 2)) STORED,
    remarks            VARCHAR(150)          NULL,
    created_at         TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT pk_attendance               PRIMARY KEY (attendance_id),
    CONSTRAINT uq_attendance_emp_date      UNIQUE (employee_id, attendance_date),
    CONSTRAINT fk_attendance_employee      FOREIGN KEY (employee_id)
        REFERENCES employees (employee_id) ON DELETE CASCADE,
    CONSTRAINT chk_attendance_status       CHECK (status IN
        ('Present', 'Absent', 'Half Day', 'Work From Home', 'On Leave')),
    CONSTRAINT chk_attendance_times        CHECK (check_out IS NULL OR check_in IS NULL OR check_out > check_in),
    CONSTRAINT chk_attendance_time_status  CHECK (
        (status IN ('Absent', 'On Leave') AND check_in IS NULL AND check_out IS NULL)
        OR (status IN ('Present', 'Half Day', 'Work From Home') AND check_in IS NOT NULL)),

    INDEX idx_attendance_date    (attendance_date),
    INDEX idx_attendance_status  (status)
) ENGINE = InnoDB COMMENT = 'Daily attendance log';


-- -------------------------------------------------------------------------------------
-- 5.2 leave_requests
-- -------------------------------------------------------------------------------------
CREATE TABLE leave_requests (
    leave_id           INT UNSIGNED      NOT NULL AUTO_INCREMENT,
    employee_id        INT UNSIGNED      NOT NULL,
    leave_type         VARCHAR(20)       NOT NULL,
    start_date         DATE              NOT NULL,
    end_date           DATE              NOT NULL,
    total_days         SMALLINT GENERATED ALWAYS AS (DATEDIFF(end_date, start_date) + 1) STORED,
    reason             VARCHAR(255)      NOT NULL,
    status             VARCHAR(15)       NOT NULL DEFAULT 'Pending',
    approved_by        INT UNSIGNED          NULL,
    applied_at         DATETIME          NOT NULL DEFAULT CURRENT_TIMESTAMP,
    reviewed_at        DATETIME              NULL,
    reviewer_comments  VARCHAR(255)          NULL,

    CONSTRAINT pk_leave_requests            PRIMARY KEY (leave_id),
    CONSTRAINT fk_leave_employee            FOREIGN KEY (employee_id)
        REFERENCES employees (employee_id) ON DELETE CASCADE,
    CONSTRAINT fk_leave_approver            FOREIGN KEY (approved_by)
        REFERENCES employees (employee_id) ON DELETE SET NULL,
    CONSTRAINT chk_leave_type               CHECK (leave_type IN
        ('Casual', 'Sick', 'Earned', 'Maternity', 'Paternity', 'Unpaid', 'Comp Off')),
    CONSTRAINT chk_leave_status             CHECK (status IN ('Pending', 'Approved', 'Rejected', 'Cancelled')),
    CONSTRAINT chk_leave_dates              CHECK (end_date >= start_date),
    CONSTRAINT chk_leave_review             CHECK (status <> 'Pending' OR reviewed_at IS NULL),
    CONSTRAINT chk_leave_review_after_apply CHECK (reviewed_at IS NULL OR reviewed_at >= applied_at),

    INDEX idx_leave_status_dates  (status, start_date, end_date),
    INDEX idx_leave_type          (leave_type)
) ENGINE = InnoDB COMMENT = 'Employee leave applications and approvals';


-- -------------------------------------------------------------------------------------
-- 5.3 payroll - monthly salary slip per employee.
--     Gross, total deductions and net pay are generated columns, so they can never
--     drift out of sync with their components.
-- -------------------------------------------------------------------------------------
CREATE TABLE payroll (
    payroll_id         INT UNSIGNED      NOT NULL AUTO_INCREMENT,
    employee_id        INT UNSIGNED      NOT NULL,
    pay_year           SMALLINT UNSIGNED NOT NULL,
    pay_month          TINYINT UNSIGNED  NOT NULL,
    days_in_month      TINYINT UNSIGNED  NOT NULL,
    paid_days          DECIMAL(4,1)      NOT NULL,
    basic_salary       DECIMAL(10,2)     NOT NULL,
    hra                DECIMAL(10,2)     NOT NULL DEFAULT 0.00,
    special_allowance  DECIMAL(10,2)     NOT NULL DEFAULT 0.00,
    bonus              DECIMAL(10,2)     NOT NULL DEFAULT 0.00,
    pf_deduction       DECIMAL(10,2)     NOT NULL DEFAULT 0.00,
    professional_tax   DECIMAL(10,2)     NOT NULL DEFAULT 0.00,
    income_tax         DECIMAL(10,2)     NOT NULL DEFAULT 0.00,
    other_deductions   DECIMAL(10,2)     NOT NULL DEFAULT 0.00,
    gross_salary       DECIMAL(12,2) GENERATED ALWAYS AS
                       (basic_salary + hra + special_allowance + bonus) STORED,
    total_deductions   DECIMAL(12,2) GENERATED ALWAYS AS
                       (pf_deduction + professional_tax + income_tax + other_deductions) STORED,
    net_salary         DECIMAL(12,2) GENERATED ALWAYS AS
                       (basic_salary + hra + special_allowance + bonus
                        - pf_deduction - professional_tax - income_tax - other_deductions) STORED,
    payment_status     VARCHAR(15)       NOT NULL DEFAULT 'Pending',
    payment_date       DATE                  NULL,
    payment_mode       VARCHAR(20)       NOT NULL DEFAULT 'Bank Transfer',
    created_at         TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT pk_payroll                 PRIMARY KEY (payroll_id),
    CONSTRAINT uq_payroll_emp_period      UNIQUE (employee_id, pay_year, pay_month),
    CONSTRAINT fk_payroll_employee        FOREIGN KEY (employee_id)
        REFERENCES employees (employee_id) ON DELETE RESTRICT,
    CONSTRAINT chk_payroll_month          CHECK (pay_month BETWEEN 1 AND 12),
    CONSTRAINT chk_payroll_year           CHECK (pay_year BETWEEN 2000 AND 2100),
    CONSTRAINT chk_payroll_days           CHECK (paid_days >= 0 AND paid_days <= days_in_month),
    CONSTRAINT chk_payroll_amounts        CHECK (basic_salary >= 0 AND hra >= 0 AND special_allowance >= 0
                                                 AND bonus >= 0 AND pf_deduction >= 0 AND professional_tax >= 0
                                                 AND income_tax >= 0 AND other_deductions >= 0),
    CONSTRAINT chk_payroll_net            CHECK (net_salary >= 0),
    CONSTRAINT chk_payroll_status         CHECK (payment_status IN ('Pending', 'Processed', 'Paid', 'On Hold')),
    CONSTRAINT chk_payroll_paid_date      CHECK (payment_status <> 'Paid' OR payment_date IS NOT NULL),
    CONSTRAINT chk_payroll_mode           CHECK (payment_mode IN ('Bank Transfer', 'Cheque', 'Cash')),

    INDEX idx_payroll_period  (pay_year, pay_month),
    INDEX idx_payroll_status  (payment_status)
) ENGINE = InnoDB COMMENT = 'Monthly payroll / salary slips (INR)';


-- =====================================================================================
-- SECTION 6 : PROJECT TABLES
-- =====================================================================================

-- -------------------------------------------------------------------------------------
-- 6.1 projects
-- -------------------------------------------------------------------------------------
CREATE TABLE projects (
    project_id          INT UNSIGNED      NOT NULL AUTO_INCREMENT,
    project_code        VARCHAR(15)       NOT NULL,
    project_name        VARCHAR(120)      NOT NULL,
    client_name         VARCHAR(120)      NOT NULL DEFAULT 'Internal',
    department_id       INT UNSIGNED      NOT NULL,
    project_manager_id  INT UNSIGNED          NULL,
    start_date          DATE              NOT NULL,
    end_date            DATE                  NULL,
    budget              DECIMAL(14,2)     NOT NULL,
    status              VARCHAR(15)       NOT NULL DEFAULT 'Planning',
    priority            VARCHAR(10)       NOT NULL DEFAULT 'Medium',
    description         VARCHAR(500)          NULL,
    created_at          TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,

    CONSTRAINT pk_projects              PRIMARY KEY (project_id),
    CONSTRAINT uq_projects_code         UNIQUE (project_code),
    CONSTRAINT uq_projects_name         UNIQUE (project_name),
    CONSTRAINT fk_projects_department   FOREIGN KEY (department_id)
        REFERENCES departments (department_id),
    CONSTRAINT fk_projects_manager      FOREIGN KEY (project_manager_id)
        REFERENCES employees (employee_id) ON DELETE SET NULL,
    CONSTRAINT chk_projects_dates       CHECK (end_date IS NULL OR end_date >= start_date),
    CONSTRAINT chk_projects_budget      CHECK (budget >= 0),
    CONSTRAINT chk_projects_status      CHECK (status IN ('Planning', 'In Progress', 'On Hold', 'Completed', 'Cancelled')),
    CONSTRAINT chk_projects_priority    CHECK (priority IN ('Low', 'Medium', 'High', 'Critical')),

    INDEX idx_projects_status  (status)
) ENGINE = InnoDB COMMENT = 'Client and internal projects';


-- -------------------------------------------------------------------------------------
-- 6.2 employee_projects - many-to-many assignment of employees to projects
-- -------------------------------------------------------------------------------------
CREATE TABLE employee_projects (
    assignment_id       INT UNSIGNED      NOT NULL AUTO_INCREMENT,
    employee_id         INT UNSIGNED      NOT NULL,
    project_id          INT UNSIGNED      NOT NULL,
    project_role        VARCHAR(40)       NOT NULL,
    allocation_percent  TINYINT UNSIGNED  NOT NULL DEFAULT 100,
    assigned_date       DATE              NOT NULL,
    release_date        DATE                  NULL,
    is_billable         BOOLEAN           NOT NULL DEFAULT TRUE,

    CONSTRAINT pk_employee_projects        PRIMARY KEY (assignment_id),
    CONSTRAINT uq_employee_project         UNIQUE (employee_id, project_id),
    CONSTRAINT fk_ep_employee              FOREIGN KEY (employee_id)
        REFERENCES employees (employee_id) ON DELETE CASCADE,
    CONSTRAINT fk_ep_project               FOREIGN KEY (project_id)
        REFERENCES projects (project_id) ON DELETE CASCADE,
    CONSTRAINT chk_ep_allocation           CHECK (allocation_percent BETWEEN 1 AND 100),
    CONSTRAINT chk_ep_dates                CHECK (release_date IS NULL OR release_date >= assigned_date),

    INDEX idx_ep_project  (project_id)
) ENGINE = InnoDB COMMENT = 'Employee-to-project assignments';


-- =====================================================================================
-- SECTION 7 : REVIEW TABLE - performance_reviews
--     overall_rating is the generated average of five 1-5 scores.
-- =====================================================================================
CREATE TABLE performance_reviews (
    review_id               INT UNSIGNED      NOT NULL AUTO_INCREMENT,
    employee_id             INT UNSIGNED      NOT NULL,
    reviewer_id             INT UNSIGNED          NULL,
    review_year             SMALLINT UNSIGNED NOT NULL,
    review_cycle            CHAR(2)           NOT NULL,
    review_date             DATE              NOT NULL,
    technical_skills        TINYINT UNSIGNED  NOT NULL,
    communication           TINYINT UNSIGNED  NOT NULL,
    teamwork                TINYINT UNSIGNED  NOT NULL,
    productivity            TINYINT UNSIGNED  NOT NULL,
    leadership              TINYINT UNSIGNED  NOT NULL,
    overall_rating          DECIMAL(2,1) GENERATED ALWAYS AS
                            ((technical_skills + communication + teamwork + productivity + leadership) / 5) STORED,
    promotion_recommended   BOOLEAN           NOT NULL DEFAULT FALSE,
    comments                VARCHAR(500)          NULL,
    review_status           VARCHAR(15)       NOT NULL DEFAULT 'Submitted',
    created_at              TIMESTAMP         NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT pk_performance_reviews     PRIMARY KEY (review_id),
    CONSTRAINT uq_review_emp_period       UNIQUE (employee_id, review_year, review_cycle),
    CONSTRAINT fk_review_employee         FOREIGN KEY (employee_id)
        REFERENCES employees (employee_id) ON DELETE CASCADE,
    CONSTRAINT fk_review_reviewer         FOREIGN KEY (reviewer_id)
        REFERENCES employees (employee_id) ON DELETE SET NULL,
    CONSTRAINT chk_review_cycle           CHECK (review_cycle IN ('H1', 'H2')),
    CONSTRAINT chk_review_scores          CHECK (technical_skills BETWEEN 1 AND 5 AND communication BETWEEN 1 AND 5
                                                 AND teamwork BETWEEN 1 AND 5 AND productivity BETWEEN 1 AND 5
                                                 AND leadership BETWEEN 1 AND 5),
    CONSTRAINT chk_review_status          CHECK (review_status IN ('Draft', 'Submitted', 'Acknowledged')),

    INDEX idx_review_period  (review_year, review_cycle)
) ENGINE = InnoDB COMMENT = 'Half-yearly performance reviews';


-- =====================================================================================
-- SECTION 8 : TRIGGERS
--     DELIMITER is understood by MySQL Workbench and the mysql CLI.
-- =====================================================================================
DELIMITER $$

-- 8.1 An employee can never be their own manager.
CREATE TRIGGER trg_employees_bi_validate
BEFORE INSERT ON employees
FOR EACH ROW
BEGIN
    IF NEW.manager_id IS NOT NULL AND NEW.employee_id IS NOT NULL AND NEW.employee_id <> 0
       AND NEW.manager_id = NEW.employee_id THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'An employee cannot be their own manager.';
    END IF;
END$$

CREATE TRIGGER trg_employees_bu_validate
BEFORE UPDATE ON employees
FOR EACH ROW
BEGIN
    IF NEW.manager_id IS NOT NULL AND NEW.manager_id = NEW.employee_id THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'An employee cannot be their own manager.';
    END IF;
END$$

-- 8.2 Keep employees.performance_rating equal to the employee's most recent review.
CREATE TRIGGER trg_reviews_ai_sync_rating
AFTER INSERT ON performance_reviews
FOR EACH ROW
BEGIN
    UPDATE employees
       SET performance_rating = (SELECT pr.overall_rating
                                   FROM performance_reviews pr
                                  WHERE pr.employee_id = NEW.employee_id
                                  ORDER BY pr.review_year DESC, pr.review_cycle DESC
                                  LIMIT 1)
     WHERE employee_id = NEW.employee_id;
END$$

CREATE TRIGGER trg_reviews_au_sync_rating
AFTER UPDATE ON performance_reviews
FOR EACH ROW
BEGIN
    UPDATE employees
       SET performance_rating = (SELECT pr.overall_rating
                                   FROM performance_reviews pr
                                  WHERE pr.employee_id = NEW.employee_id
                                  ORDER BY pr.review_year DESC, pr.review_cycle DESC
                                  LIMIT 1)
     WHERE employee_id = NEW.employee_id;
END$$

DELIMITER ;

-- =====================================================================================
-- SECTION 9 : SEED DATA
--     Order matters: parents are always loaded before children.
--     departments -> designations -> employees -> department heads -> managers
--     -> projects -> employee_projects -> leave_requests -> attendance -> payroll
--     -> performance_reviews
-- =====================================================================================
START TRANSACTION;

