-- =====================================================================================
-- SECTION 10 : VIEWS  (ready-made read models for the Python / Streamlit app)
-- =====================================================================================

-- 10.1 Full employee profile with department, designation and manager names
CREATE OR REPLACE VIEW vw_employee_details AS
SELECT
    e.employee_id,
    e.employee_code,
    CONCAT(e.first_name, ' ', e.last_name)                  AS full_name,
    e.email,
    e.phone,
    e.gender,
    e.date_of_birth,
    TIMESTAMPDIFF(YEAR, e.date_of_birth, CURDATE())          AS age,
    d.department_code,
    d.department_name,
    g.designation_title,
    g.job_level,
    e.manager_id,
    CONCAT(m.first_name, ' ', m.last_name)                   AS manager_name,
    e.salary,
    e.joining_date,
    ROUND(DATEDIFF(IFNULL(e.exit_date, CURDATE()), e.joining_date) / 365.25, 1) AS tenure_years,
    e.exit_date,
    e.city,
    e.state,
    e.employment_type,
    e.employment_status,
    e.performance_rating
FROM employees e
JOIN departments  d ON d.department_id  = e.department_id
JOIN designations g ON g.designation_id = e.designation_id
LEFT JOIN employees m ON m.employee_id  = e.manager_id;

-- 10.2 Department dashboard: headcount, salary cost and average rating
CREATE OR REPLACE VIEW vw_department_summary AS
SELECT
    d.department_id,
    d.department_code,
    d.department_name,
    d.location,
    CONCAT(h.first_name, ' ', h.last_name)                                         AS department_head,
    COUNT(e.employee_id)                                                           AS total_employees,
    SUM(e.employment_status IN ('Active', 'Probation', 'On Leave', 'Notice Period')) AS current_employees,
    ROUND(AVG(e.salary), 2)                                                        AS avg_salary,
    SUM(CASE WHEN e.exit_date IS NULL OR e.exit_date >= CURDATE() THEN e.salary ELSE 0 END) AS annual_salary_cost,
    ROUND(AVG(e.performance_rating), 2)                                            AS avg_rating,
    d.annual_budget
FROM departments d
LEFT JOIN employees e ON e.department_id = d.department_id
LEFT JOIN employees h ON h.employee_id   = d.head_employee_id
GROUP BY d.department_id, d.department_code, d.department_name, d.location,
         h.first_name, h.last_name, d.annual_budget;

-- 10.3 Monthly attendance summary per employee
CREATE OR REPLACE VIEW vw_attendance_monthly_summary AS
SELECT
    a.employee_id,
    e.employee_code,
    CONCAT(e.first_name, ' ', e.last_name)       AS full_name,
    YEAR(a.attendance_date)                      AS att_year,
    MONTH(a.attendance_date)                     AS att_month,
    COUNT(*)                                     AS working_days,
    SUM(a.status = 'Present')                    AS present_days,
    SUM(a.status = 'Work From Home')             AS wfh_days,
    SUM(a.status = 'Half Day')                   AS half_days,
    SUM(a.status = 'On Leave')                   AS leave_days,
    SUM(a.status = 'Absent')                     AS absent_days,
    ROUND(AVG(a.work_hours), 2)                  AS avg_work_hours,
    ROUND(100 * SUM(a.status IN ('Present', 'Work From Home')) / COUNT(*), 1) AS attendance_pct
FROM attendance a
JOIN employees e ON e.employee_id = a.employee_id
GROUP BY a.employee_id, e.employee_code, e.first_name, e.last_name,
         YEAR(a.attendance_date), MONTH(a.attendance_date);

-- 10.4 Payroll totals per month and department
CREATE OR REPLACE VIEW vw_payroll_monthly_summary AS
SELECT
    p.pay_year,
    p.pay_month,
    d.department_name,
    COUNT(*)                     AS employees_paid,
    SUM(p.gross_salary)          AS total_gross,
    SUM(p.total_deductions)      AS total_deductions,
    SUM(p.net_salary)            AS total_net,
    ROUND(AVG(p.net_salary), 2)  AS avg_net
FROM payroll p
JOIN employees   e ON e.employee_id   = p.employee_id
JOIN departments d ON d.department_id = e.department_id
GROUP BY p.pay_year, p.pay_month, d.department_name;

-- 10.5 Project teams with current allocation
CREATE OR REPLACE VIEW vw_project_team AS
SELECT
    p.project_code,
    p.project_name,
    p.client_name,
    p.status                                AS project_status,
    e.employee_code,
    CONCAT(e.first_name, ' ', e.last_name)  AS employee_name,
    ep.project_role,
    ep.allocation_percent,
    ep.assigned_date,
    ep.release_date,
    ep.is_billable
FROM employee_projects ep
JOIN projects  p ON p.project_id  = ep.project_id
JOIN employees e ON e.employee_id = ep.employee_id;


-- =====================================================================================
-- SECTION 11 : STORED PROCEDURES  (callable from Python with cursor.callproc)
-- =====================================================================================
DELIMITER $$

-- 11.1 List employees of a department by department code, e.g. CALL sp_get_employees_by_department('ENG');
DROP PROCEDURE IF EXISTS sp_get_employees_by_department$$
CREATE PROCEDURE sp_get_employees_by_department(IN p_department_code VARCHAR(10))
BEGIN
    SELECT employee_code, full_name, designation_title, manager_name, salary, employment_status, performance_rating
      FROM vw_employee_details
     WHERE department_code = p_department_code
     ORDER BY job_level DESC, full_name;
END$$

-- 11.2 Attendance report for one employee between two dates
DROP PROCEDURE IF EXISTS sp_employee_attendance_report$$
CREATE PROCEDURE sp_employee_attendance_report(IN p_employee_id INT UNSIGNED, IN p_from DATE, IN p_to DATE)
BEGIN
    SELECT attendance_date, DAYNAME(attendance_date) AS day_name, status, check_in, check_out, work_hours, remarks
      FROM attendance
     WHERE employee_id = p_employee_id
       AND attendance_date BETWEEN p_from AND p_to
     ORDER BY attendance_date;
END$$

-- 11.3 Department-wise payroll for a month, e.g. CALL sp_department_payroll(2026, 9);
DROP PROCEDURE IF EXISTS sp_department_payroll$$
CREATE PROCEDURE sp_department_payroll(IN p_year SMALLINT, IN p_month TINYINT)
BEGIN
    SELECT department_name, employees_paid, total_gross, total_deductions, total_net, avg_net
      FROM vw_payroll_monthly_summary
     WHERE pay_year = p_year AND pay_month = p_month
     ORDER BY total_net DESC;
END$$

-- 11.4 Salary hike inside a transaction, with salary-band validation and rollback on error
DROP PROCEDURE IF EXISTS sp_apply_salary_hike$$
CREATE PROCEDURE sp_apply_salary_hike(IN p_employee_id INT UNSIGNED, IN p_percent DECIMAL(5,2))
BEGIN
    DECLARE v_new_salary DECIMAL(12,2);
    DECLARE v_max_salary DECIMAL(12,2);

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    IF p_percent <= 0 OR p_percent > 50 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Hike percent must be between 0 and 50.';
    END IF;

    START TRANSACTION;

    SELECT ROUND(e.salary * (1 + p_percent / 100), -3), d.max_salary
      INTO v_new_salary, v_max_salary
      FROM employees e
      JOIN designations d ON d.designation_id = e.designation_id
     WHERE e.employee_id = p_employee_id
       FOR UPDATE;

    IF v_new_salary IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Employee not found.';
    END IF;

    IF v_new_salary > v_max_salary THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'New salary exceeds the designation salary band.';
    END IF;

    UPDATE employees SET salary = v_new_salary WHERE employee_id = p_employee_id;

    COMMIT;

    SELECT employee_id, employee_code, salary AS new_salary FROM employees WHERE employee_id = p_employee_id;
END$$

DELIMITER ;


-- =====================================================================================
-- SECTION 12 : DATA VERIFICATION  (run after loading; integrity checks should return 0)
-- =====================================================================================

-- 12.1 Row counts per table
SELECT 'departments' AS table_name, COUNT(*) AS total_rows FROM departments
UNION ALL SELECT 'designations',        COUNT(*) FROM designations
UNION ALL SELECT 'employees',           COUNT(*) FROM employees
UNION ALL SELECT 'managers',            COUNT(*) FROM managers
UNION ALL SELECT 'projects',            COUNT(*) FROM projects
UNION ALL SELECT 'employee_projects',   COUNT(*) FROM employee_projects
UNION ALL SELECT 'leave_requests',      COUNT(*) FROM leave_requests
UNION ALL SELECT 'attendance',          COUNT(*) FROM attendance
UNION ALL SELECT 'payroll',             COUNT(*) FROM payroll
UNION ALL SELECT 'performance_reviews', COUNT(*) FROM performance_reviews;

-- 12.2 Integrity checks (every issue_count should be 0)
SELECT 'Salary outside designation band' AS check_name, COUNT(*) AS issue_count
  FROM employees e JOIN designations d ON d.designation_id = e.designation_id
 WHERE e.salary NOT BETWEEN d.min_salary AND d.max_salary
UNION ALL
SELECT 'Employee reports to someone not in managers table', COUNT(*)
  FROM employees e
 WHERE e.manager_id IS NOT NULL AND e.manager_id NOT IN (SELECT employee_id FROM managers)
UNION ALL
SELECT 'Attendance outside employment period', COUNT(*)
  FROM attendance a JOIN employees e ON e.employee_id = a.employee_id
 WHERE a.attendance_date < e.joining_date OR (e.exit_date IS NOT NULL AND a.attendance_date > e.exit_date)
UNION ALL
SELECT 'On Leave attendance without approved leave', COUNT(*)
  FROM attendance a
 WHERE a.status = 'On Leave'
   AND NOT EXISTS (SELECT 1 FROM leave_requests l
                    WHERE l.employee_id = a.employee_id AND l.status = 'Approved'
                      AND a.attendance_date BETWEEN l.start_date AND l.end_date)
UNION ALL
SELECT 'Current project allocation above 100%', COUNT(*)
  FROM (SELECT employee_id FROM employee_projects WHERE release_date IS NULL
        GROUP BY employee_id HAVING SUM(allocation_percent) > 100) x;


-- =====================================================================================
-- SECTION 13 : SQL PRACTICE EXAMPLES
--     Safe to run as part of the full script. Data-changing demos work on a demo
--     employee (EMP0111) that is deleted again at the end, and the company-wide salary
--     demo is rolled back, so the seed data is left exactly as loaded.
-- =====================================================================================

-- -------------------------------------------------------------------------------------
-- 13.1 CREATE  - a holiday calendar table and an extra composite index
-- -------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS company_holidays (
    holiday_date   DATE         NOT NULL,
    holiday_name   VARCHAR(80)  NOT NULL,
    holiday_type   VARCHAR(20)  NOT NULL DEFAULT 'National',
    CONSTRAINT pk_company_holidays PRIMARY KEY (holiday_date),
    CONSTRAINT chk_holiday_type    CHECK (holiday_type IN ('National', 'Festival', 'Optional'))
) ENGINE = InnoDB;

CREATE INDEX idx_attendance_emp_status ON attendance (employee_id, status);

-- -------------------------------------------------------------------------------------
-- 13.2 INSERT  - multi-row, single-row and INSERT ... SELECT
-- -------------------------------------------------------------------------------------
INSERT INTO company_holidays (holiday_date, holiday_name, holiday_type) VALUES
('2026-01-26', 'Republic Day',     'National'),
('2026-03-04', 'Holi',             'Festival'),
('2026-05-01', 'Labour Day',       'National'),
('2026-08-15', 'Independence Day', 'National'),
('2026-10-02', 'Gandhi Jayanti',   'National'),
('2026-12-25', 'Christmas',        'Festival');

-- Look up foreign-key values by business code instead of hard-coding IDs
SET @eng_dept_id = (SELECT department_id  FROM departments  WHERE department_code   = 'ENG');
SET @se_desig_id = (SELECT designation_id FROM designations WHERE designation_title = 'Software Engineer');
SET @tl_id       = (SELECT employee_id    FROM employees    WHERE employee_code     = 'EMP0007');

INSERT INTO employees
    (employee_code, first_name, last_name, email, phone, date_of_birth, gender,
     department_id, designation_id, manager_id, salary, joining_date, address, city, state,
     postal_code, employment_type, employment_status)
VALUES
    ('EMP0111', 'Rhea', 'Kapadia', 'rhea.kapadia@orbitwave.in', '+919812345670', '1999-03-14', 'Female',
     @eng_dept_id, @se_desig_id, @tl_id, 1150000.00, '2026-10-26',
     'Flat 704, Orchid Heights, HSR Layout Sector 2', 'Bengaluru', 'Karnataka',
     '560102', 'Full-Time', 'Probation');

SET @demo_emp_id = LAST_INSERT_ID();

-- INSERT ... SELECT: put the new joiner on the same active project as her manager
INSERT INTO employee_projects (employee_id, project_id, project_role, allocation_percent, assigned_date, is_billable)
SELECT @demo_emp_id, ep.project_id, 'Developer', 50, '2026-10-26', TRUE
  FROM employee_projects ep
  JOIN projects p ON p.project_id = ep.project_id
 WHERE ep.employee_id = @tl_id AND p.status = 'In Progress'
 ORDER BY ep.project_id
 LIMIT 1;

-- -------------------------------------------------------------------------------------
-- 13.3 SELECT  - columns, aliases, DISTINCT, LIMIT/OFFSET (pagination for Streamlit)
-- -------------------------------------------------------------------------------------
SELECT employee_code, first_name, last_name, email, city FROM employees;

SELECT employee_code AS `Code`, CONCAT(first_name, ' ', last_name) AS `Employee Name`,
       ROUND(salary / 12, 2) AS `Monthly CTC`
  FROM employees;

SELECT DISTINCT city, state FROM employees ORDER BY state, city;

-- Page 2 of the employee list, 20 rows per page
SELECT employee_code, first_name, last_name FROM employees ORDER BY employee_id LIMIT 20 OFFSET 20;

-- -------------------------------------------------------------------------------------
-- 13.4 WHERE  - comparison, BETWEEN, IN, LIKE, IS NULL, AND / OR
-- -------------------------------------------------------------------------------------
SELECT employee_code, first_name, last_name, salary
  FROM employees
 WHERE salary > 2000000;

SELECT employee_code, first_name, last_name, joining_date
  FROM employees
 WHERE joining_date BETWEEN '2024-01-01' AND '2024-12-31';

SELECT employee_code, first_name, last_name, city
  FROM employees
 WHERE city IN ('Pune', 'Mumbai', 'Hyderabad');

SELECT employee_code, first_name, last_name, email
  FROM employees
 WHERE last_name LIKE 'S%';

SELECT employee_code, first_name, last_name, employment_status
  FROM employees
 WHERE manager_id IS NULL OR performance_rating IS NULL;

SELECT employee_code, first_name, last_name, gender, salary, performance_rating
  FROM employees
 WHERE gender = 'Female' AND performance_rating >= 4.0 AND employment_status = 'Active';

-- -------------------------------------------------------------------------------------
-- 13.5 ORDER BY  - single and multiple sort keys
-- -------------------------------------------------------------------------------------
SELECT employee_code, first_name, last_name, salary
  FROM employees
 ORDER BY salary DESC
 LIMIT 10;

SELECT employee_code, first_name, last_name, department_id, joining_date
  FROM employees
 ORDER BY department_id ASC, joining_date ASC;

-- -------------------------------------------------------------------------------------
-- 13.6 AGGREGATE FUNCTIONS  - COUNT, SUM, AVG, MIN, MAX
-- -------------------------------------------------------------------------------------
SELECT COUNT(*)               AS total_employees,
       SUM(salary)            AS total_annual_ctc,
       ROUND(AVG(salary), 2)  AS avg_salary,
       MIN(salary)            AS min_salary,
       MAX(salary)            AS max_salary,
       ROUND(AVG(performance_rating), 2) AS avg_rating
  FROM employees
 WHERE exit_date IS NULL;

SELECT COUNT(*) AS approved_leaves, SUM(total_days) AS total_leave_days
  FROM leave_requests
 WHERE status = 'Approved' AND YEAR(start_date) = 2026;

-- -------------------------------------------------------------------------------------
-- 13.7 GROUP BY + HAVING
-- -------------------------------------------------------------------------------------
SELECT department_id, COUNT(*) AS headcount, ROUND(AVG(salary), 2) AS avg_salary
  FROM employees
 GROUP BY department_id
 ORDER BY headcount DESC;

SELECT city, COUNT(*) AS employees
  FROM employees
 GROUP BY city
HAVING COUNT(*) >= 5
 ORDER BY employees DESC;

SELECT employment_status, gender, COUNT(*) AS total
  FROM employees
 GROUP BY employment_status, gender
 ORDER BY employment_status, gender;

SELECT leave_type, status, COUNT(*) AS requests, SUM(total_days) AS days
  FROM leave_requests
 GROUP BY leave_type, status
 ORDER BY leave_type, status;

-- -------------------------------------------------------------------------------------
-- 13.8 JOINS
-- -------------------------------------------------------------------------------------
-- INNER JOIN: employee with department and designation
SELECT e.employee_code, CONCAT(e.first_name, ' ', e.last_name) AS employee,
       d.department_name, g.designation_title, e.salary
  FROM employees e
  INNER JOIN departments  d ON d.department_id  = e.department_id
  INNER JOIN designations g ON g.designation_id = e.designation_id
 ORDER BY d.department_name, g.job_level DESC;

-- SELF JOIN: employee and their manager
SELECT e.employee_code,
       CONCAT(e.first_name, ' ', e.last_name) AS employee,
       CONCAT(m.first_name, ' ', m.last_name) AS manager
  FROM employees e
  LEFT JOIN employees m ON m.employee_id = e.manager_id
 ORDER BY manager, employee;

-- LEFT JOIN: department headcount including departments with no employees
SELECT d.department_name, COUNT(e.employee_id) AS headcount
  FROM departments d
  LEFT JOIN employees e ON e.department_id = d.department_id
 GROUP BY d.department_name;

-- LEFT JOIN anti-join: employees not assigned to any project
SELECT e.employee_code, CONCAT(e.first_name, ' ', e.last_name) AS employee, d.department_name
  FROM employees e
  JOIN departments d ON d.department_id = e.department_id
  LEFT JOIN employee_projects ep ON ep.employee_id = e.employee_id
 WHERE ep.assignment_id IS NULL;

-- Multi-table JOIN: project teams with roles and managers
SELECT p.project_code, p.project_name, p.status,
       CONCAT(pm.first_name, ' ', pm.last_name) AS project_manager,
       CONCAT(e.first_name, ' ', e.last_name)   AS team_member,
       ep.project_role, ep.allocation_percent
  FROM projects p
  JOIN employee_projects ep ON ep.project_id = p.project_id
  JOIN employees e          ON e.employee_id = ep.employee_id
  LEFT JOIN employees pm    ON pm.employee_id = p.project_manager_id
 WHERE p.status = 'In Progress'
 ORDER BY p.project_code, ep.allocation_percent DESC;

-- JOIN + GROUP BY: September 2026 attendance per department
SELECT d.department_name,
       SUM(a.status = 'Present')        AS present,
       SUM(a.status = 'Work From Home') AS wfh,
       SUM(a.status = 'On Leave')       AS on_leave,
       SUM(a.status = 'Absent')         AS absent,
       ROUND(AVG(a.work_hours), 2)      AS avg_hours
  FROM attendance a
  JOIN employees e   ON e.employee_id   = a.employee_id
  JOIN departments d ON d.department_id = e.department_id
 WHERE a.attendance_date BETWEEN '2026-09-01' AND '2026-09-30'
 GROUP BY d.department_name
 ORDER BY d.department_name;

-- JOIN: pending leave requests with the manager who must approve them
SELECT l.leave_id, e.employee_code, CONCAT(e.first_name, ' ', e.last_name) AS employee,
       l.leave_type, l.start_date, l.end_date, l.total_days,
       CONCAT(m.first_name, ' ', m.last_name) AS approver
  FROM leave_requests l
  JOIN employees e      ON e.employee_id = l.employee_id
  LEFT JOIN employees m ON m.employee_id = e.manager_id
 WHERE l.status = 'Pending'
 ORDER BY l.start_date;

-- -------------------------------------------------------------------------------------
-- 13.9 SUBQUERIES, CTEs and WINDOW FUNCTIONS
-- -------------------------------------------------------------------------------------
-- Scalar subquery: employees earning above the company average
SELECT employee_code, first_name, last_name, salary
  FROM employees
 WHERE salary > (SELECT AVG(salary) FROM employees)
 ORDER BY salary DESC;

-- IN subquery: employees working on Critical / High priority projects
SELECT employee_code, first_name, last_name
  FROM employees
 WHERE employee_id IN (SELECT ep.employee_id
                         FROM employee_projects ep
                         JOIN projects p ON p.project_id = ep.project_id
                        WHERE p.priority IN ('Critical', 'High') AND ep.release_date IS NULL);

-- Correlated subquery: highest-paid employee in each department
SELECT e.department_id, e.employee_code, e.first_name, e.last_name, e.salary
  FROM employees e
 WHERE e.salary = (SELECT MAX(e2.salary) FROM employees e2 WHERE e2.department_id = e.department_id);

-- EXISTS: managers who have at least one pending leave to approve
SELECT m.employee_code, m.first_name, m.last_name
  FROM employees m
 WHERE EXISTS (SELECT 1
                 FROM leave_requests l
                 JOIN employees e ON e.employee_id = l.employee_id
                WHERE e.manager_id = m.employee_id AND l.status = 'Pending');

-- Derived table: departments whose average rating is above the company average
SELECT x.department_name, x.avg_rating
  FROM (SELECT d.department_name, ROUND(AVG(e.performance_rating), 2) AS avg_rating
          FROM employees e
          JOIN departments d ON d.department_id = e.department_id
         GROUP BY d.department_name) AS x
 WHERE x.avg_rating > (SELECT AVG(performance_rating) FROM employees)
 ORDER BY x.avg_rating DESC;

-- CTE + window function: top 3 earners per department
WITH ranked AS (
    SELECT d.department_name, e.employee_code,
           CONCAT(e.first_name, ' ', e.last_name) AS employee, e.salary,
           DENSE_RANK() OVER (PARTITION BY e.department_id ORDER BY e.salary DESC) AS salary_rank
      FROM employees e
      JOIN departments d ON d.department_id = e.department_id
)
SELECT department_name, salary_rank, employee_code, employee, salary
  FROM ranked
 WHERE salary_rank <= 3
 ORDER BY department_name, salary_rank;

-- Window function: rating trend between review cycles
SELECT employee_id, review_year, review_cycle, overall_rating,
       LAG(overall_rating) OVER (PARTITION BY employee_id ORDER BY review_year, review_cycle) AS previous_rating,
       overall_rating - LAG(overall_rating) OVER (PARTITION BY employee_id ORDER BY review_year, review_cycle) AS change_in_rating
  FROM performance_reviews
 ORDER BY employee_id, review_year, review_cycle;

-- Recursive CTE: the full reporting chain under the CTO (EMP0002)
WITH RECURSIVE org_chart AS (
    SELECT employee_id, employee_code, CONCAT(first_name, ' ', last_name) AS employee, manager_id, 0 AS depth
      FROM employees
     WHERE employee_code = 'EMP0002'
    UNION ALL
    SELECT e.employee_id, e.employee_code, CONCAT(e.first_name, ' ', e.last_name), e.manager_id, oc.depth + 1
      FROM employees e
      JOIN org_chart oc ON e.manager_id = oc.employee_id
)
SELECT CONCAT(REPEAT('    ', depth), employee) AS hierarchy, employee_code, depth
  FROM org_chart
 ORDER BY depth, employee;

-- Views and stored procedures in use
SELECT * FROM vw_department_summary ORDER BY total_employees DESC;
SELECT * FROM vw_attendance_monthly_summary WHERE att_year = 2026 AND att_month = 9 ORDER BY attendance_pct ASC LIMIT 10;
CALL sp_get_employees_by_department('QA');
CALL sp_department_payroll(2026, 9);
CALL sp_employee_attendance_report(7, '2026-10-01', '2026-10-23');

-- -------------------------------------------------------------------------------------
-- 13.10 UPDATE
-- -------------------------------------------------------------------------------------
-- Single-row update: the demo employee's address
UPDATE employees
   SET address = 'Flat 1102, Prestige Lakeside, Whitefield', postal_code = '560066'
 WHERE employee_id = @demo_emp_id;

-- Update via stored procedure inside a transaction (8% hike, validated against salary band)
CALL sp_apply_salary_hike(@demo_emp_id, 8.00);

-- Update with CASE: move the demo employee from Probation to Active
UPDATE employees
   SET employment_status = CASE WHEN employment_status = 'Probation' THEN 'Active' ELSE employment_status END
 WHERE employee_id = @demo_emp_id;

SELECT employee_code, first_name, last_name, salary, address, employment_status
  FROM employees WHERE employee_id = @demo_emp_id;

-- -------------------------------------------------------------------------------------
-- 13.11 TRANSACTIONS
-- -------------------------------------------------------------------------------------
-- Transaction 1 (COMMIT): the demo employee applies for leave and the manager approves it.
START TRANSACTION;

INSERT INTO leave_requests (employee_id, leave_type, start_date, end_date, reason, status, applied_at)
VALUES (@demo_emp_id, 'Casual', '2026-11-09', '2026-11-10', 'Family function in hometown', 'Pending', '2026-10-27 10:15:00');

SET @demo_leave_id = LAST_INSERT_ID();

UPDATE leave_requests
   SET status = 'Approved', approved_by = @tl_id,
       reviewed_at = '2026-10-27 15:30:00', reviewer_comments = 'Approved'
 WHERE leave_id = @demo_leave_id;

COMMIT;

SELECT leave_id, employee_id, leave_type, start_date, end_date, total_days, status, approved_by
  FROM leave_requests WHERE leave_id = @demo_leave_id;

-- Transaction 2 (SAVEPOINT + ROLLBACK): trial company-wide hike that is undone.
START TRANSACTION;

SELECT SUM(salary) AS payroll_before FROM employees;

UPDATE employees SET salary = salary * 1.05 WHERE department_id = @eng_dept_id;
SAVEPOINT after_engineering_hike;

UPDATE employees SET salary = salary * 1.03 WHERE department_id <> @eng_dept_id;
SELECT SUM(salary) AS payroll_after_both_hikes FROM employees;

ROLLBACK TO SAVEPOINT after_engineering_hike;   -- undo only the 3% hike
SELECT SUM(salary) AS payroll_after_partial_rollback FROM employees;

ROLLBACK;                                       -- undo everything in this transaction
SELECT SUM(salary) AS payroll_after_full_rollback FROM employees;

