-- 13.12 DELETE
-- -------------------------------------------------------------------------------------
-- Delete a single child row
DELETE FROM employee_projects WHERE employee_id = @demo_emp_id;

-- Delete the demo employee. ON DELETE CASCADE removes her leave request automatically.
DELETE FROM employees WHERE employee_id = @demo_emp_id;

SELECT COUNT(*) AS demo_leaves_left FROM leave_requests WHERE employee_id = @demo_emp_id;

